// Directive-free: imported by server pages, metadata and JSON-LD.
// Generated by scripts/research/build_landscape.py from the raw, sourced vendor research in
// scripts/research/*.json. Do not edit landscape.json by hand; fix the raw record (or corrections.json) and rebuild.
import raw from "./landscape.json";
import type { MapPoint } from "@/components/research/charts";

export type CapValue = "yes" | "partial" | "no" | "unknown";
export type CapKey =
  | "handwritten_reading" | "subjective_ai_marking" | "stem_maths" | "rubric_marking_scheme"
  | "partial_marks_feedback" | "typed_answers" | "indian_languages"
  | "bulk_scan_ingest" | "student_identification" | "annotated_copy" | "teacher_review"
  | "question_paper_import" | "public_api" | "integrity_checks";

export type Vendor = {
  name: string;
  company: string | null;
  region: "india" | "global" | "evalezy";
  hq: string | null;
  segment: string;
  website: string;
  target: string | null;
  pricing: {
    public_pricing?: boolean | null;
    model?: string | null;
    entry_price?: { amount: number | null; currency: string | null; period: string | null; plan_name?: string | null; notes?: string | null } | null;
    free_plan?: boolean | null;
  };
  capabilities: Record<CapKey, { value: CapValue; evidence: string }>;
  marking: number;
  workflow: number;
  breadth: number;
  scale: { customers_claimed?: string | null; funding_or_owner_notes?: string | null };
  notable: string | null;
  notableSource: string | null;
  sources: Record<string, string>;
  asOf: string;
};

const data = raw as unknown as { capLabels: Record<CapKey, string>; marking: CapKey[]; workflow: CapKey[]; vendors: Vendor[] };

export const CAP_LABELS = data.capLabels;
export const MARKING_CAPS = data.marking;
export const WORKFLOW_CAPS = data.workflow;
export const ALL_CAPS: CapKey[] = [...MARKING_CAPS, ...WORKFLOW_CAPS];
export const VENDORS: Vendor[] = data.vendors;
export const OTHERS: Vendor[] = VENDORS.filter((v) => v.region !== "evalezy");
export const EVALEZY: Vendor = VENDORS.find((v) => v.region === "evalezy")!;

export const LANDSCAPE_SLUG = "ai-answer-sheet-evaluation-landscape-2026";
export const LANDSCAPE_CSV = "/research/ai-answer-sheet-evaluation-landscape-2026.csv";
export const RESEARCH_PUBLISHED = "2026-10-22";
export const RESEARCH_UPDATED = "2026-10-22";

export const SEGMENT_LABELS: Record<string, string> = {
  "ai-copy-checking": "AI copy checking",
  "upsc-answer-writing": "UPSC answer writing",
  osm: "On-screen marking",
  "handwritten-grading": "Scan-and-grade",
  omr: "OMR / bubble sheets",
  "ai-grading-assistant": "AI grading assistant",
  "lms-ai": "LMS with AI grading",
};

/** How many of the other vendors document a capability with this value (default: natively, "yes"). */
export function capCount(cap: CapKey, value: CapValue = "yes", pool: Vendor[] = OTHERS) {
  return pool.filter((v) => v.capabilities[cap].value === value).length;
}

/** Vendors that document every capability in the list natively. */
export function withAll(caps: CapKey[], pool: Vendor[] = OTHERS) {
  return pool.filter((v) => caps.every((c) => v.capabilities[c].value === "yes"));
}

export function averageBreadth(filter: (v: Vendor) => boolean) {
  const set = OTHERS.filter(filter);
  return { n: set.length, avg: set.length ? set.reduce((s, v) => s + v.breadth, 0) / set.length : 0 };
}

/** First source URL we hold for a vendor, preferring capabilities, then pricing, then the homepage. */
export function primarySource(v: Vendor) {
  const s = v.sources;
  const capKey = Object.keys(s).find((k) => k.startsWith("capabilities"));
  return (capKey && s[capKey]) || s.pricing || s.homepage || Object.values(s)[0] || v.website;
}

export function formatEntryPrice(v: Vendor) {
  const p = v.pricing;
  const e = p.entry_price;
  if (!p.public_pricing && !e?.amount) return p.model === "quote" ? "On request" : "Not published";
  if (!e || e.amount == null) return p.free_plan ? "Free plan" : p.model ?? "Not published";
  const cur = e.currency === "INR" ? "₹" : e.currency === "USD" ? "$" : e.currency === "GBP" ? "£" : e.currency === "EUR" ? "€" : e.currency === "AUD" ? "A$" : `${e.currency ?? ""} `;
  return `${cur}${e.amount.toLocaleString("en-IN")}${e.period ? ` / ${e.period}` : ""}`;
}

/**
 * Map points. Every vendor keeps a tooltip; labels are drawn for Evalezy and for vendors whose names are
 * listed in LABELS (chosen after seeing the data, to avoid collisions). Sides nudge label placement.
 */
export const MAP_LABELS: Record<string, MapPoint["labelSide"]> = {};

export function landscapeMapPoints(labels: Record<string, MapPoint["labelSide"]> = MAP_LABELS): MapPoint[] {
  return VENDORS.map((v) => ({
    label: v.name,
    x: v.marking,
    y: v.workflow,
    series: v.region,
    detail: `marking ${v.marking}%, workflow ${v.workflow}% (${v.breadth} of 14) · ${SEGMENT_LABELS[v.segment] ?? v.segment}`,
    showLabel: v.region === "evalezy" || v.name in labels,
    labelSide: labels[v.name] ?? (v.region === "evalezy" ? "below-left" : "right"),
  }));
}
